package basics;

public class SumOfNaturalNumbers {
	public static void main(String[] args) {
		// TODO Auto-generated method stub
		  int i = 1;
	        int sum = 0;

	        while (i <= 50) {
	            sum = sum + i;
	            i++;
	        }

	        System.out.println("Sum = " + sum);

	}
	

}
